export const SLUG_TO_ENTRY: ReadonlyMap<string, KeywordEntry> = new Map([
  ["jpa-auditing", { slug: "jpa-auditing", title: { ko: "JPA Auditing 딥다이브", en: "JPA Auditing Deep Dive" }, summary: { ko: "Spring Data JPA의 @EnableJpaAuditing과 AuditingEntityListener가 엔티티 lifecycle 콜백 위에 올라타 @CreatedDate·@LastModifiedDate를 자동 주입하는 내부 배선과 실행 흐름을 이해할 수 있습니다. persist·update·벌크 UPDATE 세 경로의 차이와 updated_at이 stale이 되는 실전 함정도 함께 다룹니다.", en: "Understand how Spring Data JPA's @EnableJpaAuditing and AuditingEntityListener hook into JPA lifecycle callbacks to inject @CreatedDate and @LastModifiedDate. Covers the wiring, execution paths for persist/update/bulk-update, and the pitfalls that leave updated_at stale." } }],
  ["testcontainers-essentials", { slug: "testcontainers-essentials", title: { ko: "Testcontainers 입문", en: "Testcontainers Essentials" }, summary: { ko: "Testcontainers를 처음 만지는 사람이 BOM 의존성 추가, GenericContainer로 첫 컨테이너 띄우기, MySQL, Redis, Kafka 모듈 사용, Spring Boot 통합(@DynamicPropertySource와 @ServiceConnection), 그리고 per-test, per-class, Singleton 라이프사이클 선택 기준까지 한 번에 훑습니다.", en: "A getting-started guide to Testcontainers. Covers BOM dependencies, the GenericContainer entry point, MySQL, Redis, and Kafka modules, Spring Boot integration via @DynamicPropertySource and @ServiceConnection, and the three lifecycle patterns: per-test, per-class, and singleton reuse." } }],
  ["spring-grpc-starter", { slug: "spring-grpc-starter", title: { ko: "spring-grpc", en: "spring-grpc" }, summary: { ko: "Spring 공식 spring-grpc 스타터가 gRPC 서버와 클라이언트를 어떻게 자동화하는지 이해할 수 있습니다. @GrpcService와 @ImportGrpcClients가 줄여주는 보일러플레이트, application.properties 설정 키, 인터셉터·TLS·Observability 통합까지 사용법 중심으로 살펴봅니다.", en: "Understand how the official spring-grpc starter automates gRPC servers and clients on Spring Boot. Covers the boilerplate that @GrpcService and @ImportGrpcClients eliminate, the application.properties keys, and how interceptors, TLS, and observability plug in." } }],
  ["modifying-vs-dirty-checking", { slug: "modifying-vs-dirty-checking", title: { ko: "@Modifying vs Dirty Checking", en: "@Modifying vs Dirty Checking" }, summary: { ko: "Spring Data JPA에서 데이터베이스 레코드를 수정하는 두 가지 방법(@Modifying JPQL UPDATE와 도메인 객체 변경을 통한 Dirty Checking)이 영속성 컨텍스트와 어떻게 다르게 상호작용하는지 이해할 수 있습니다. 1차 캐시 stale, lifecycle 우회, lost update 같은 실전 함정이 모두 같은 차이에서 나온다는 것을 정리합니다.", en: "Understand how the two update methods in Spring Data JPA (@Modifying JPQL UPDATE and domain object mutation via Dirty Checking) interact with the persistence context differently. Follow the difference that produces stale first-level cache, lifecycle bypass, and lost update pitfalls." } }],
  ["micrometer-timer-essentials", { slug: "micrometer-timer-essentials", title: { ko: "Micrometer Timer 입문", en: "Micrometer Timer Essentials" }, summary: { ko: "Micrometer Timer가 기록하는 네 가지(count, totalTime, max, distribution)와 세 가지 측정 API(record, Timer.Sample, @Timed)를 이해하고, 비즈니스 코드를 덜 더럽히는 4단계 전략(자동 계측, @Timed, Observation, 직접 Aspect)을 구분할 수 있습니다. 측정은 caller thread에서 동기이지만 lock-free라 blocking이 아니라는 실행 모델과 Prometheus 연동까지 다룹니다.", en: "The four values a Micrometer Timer records (count, totalTime, max, distribution), the three timing APIs (record, Timer.Sample, @Timed), and a four-step ladder (auto-instrumentation, @Timed, Observation, Aspect) to keep business code clean. Plus the execution model and Prometheus wiring." } }],
  ["back-of-the-envelope-estimation", { slug: "back-of-the-envelope-estimation", title: { ko: "개략적인 규모 추정", en: "Back-of-the-envelope Estimation" }, summary: { ko: "시스템 설계 면접에서 자주 묻는 용량·응답지연·가용률 추정의 기본 단위와 제프 딘이 정리한 수치들을 한 번에 익힙니다. 트위터 규모 가정으로 QPS와 저장소를 추정하는 사고 절차도 같이 따라가 봅니다.", en: "A short field guide to back-of-the-envelope estimation: powers of two, Jeff Dean's latency numbers, availability tables, and a Twitter-scale QPS / storage walkthrough." } }],
  ["single-point-of-failure", { slug: "single-point-of-failure", title: { ko: "단일 장애 지점 (SPOF)", en: "Single Point Of Failure (SPOF)" }, summary: { ko: "SPOF(단일 장애점)가 왜 분산 시스템 설계의 근본 제약인지 이해하고, HW/네트워크/DB/프로세스/암묵적 SPOF의 계층별 발견 방법과 단계적 이중화 사다리로 어떤 SPOF를 제거하고 어떤 것을 받아들일지 판단 기준을 얻을 수 있습니다.", en: "Why SPOF is a foundational constraint in distributed system design. Learn to uncover SPOFs across hardware, network, database, process, and implicit layers, and gain criteria for deciding which to remove and which to accept through a staged redundancy ladder." } }],
  ["sync-async-blocking-nonblocking", { slug: "sync-async-blocking-nonblocking", title: { ko: "동기·비동기와 블로킹·논블로킹", en: "Sync/Async and Blocking/Non-Blocking" }, summary: { ko: "Sync/Async와 Blocking/Non-Blocking은 서로 다른 축임을 음식점 비유로 먼저 이해하고, 4가지 조합을 실제 기술(Tomcat, Nginx, Node.js, io_uring, Virtual Thread)에 매핑합니다. 직관 → 두 단계 read() → C10K → 실제 시스템 순서로 따라갑니다.", en: "Build intuition for Sync/Async vs Blocking/Non-Blocking through a restaurant analogy, then map the four combinations to real systems (Tomcat, Nginx, Node.js, io_uring, Virtual Threads). Goes intuition → two-stage read() → C10K → real systems." } }],
  ["two-generals-problem", { slug: "two-generals-problem", title: { ko: "Two Generals' Problem 소개", en: "Two Generals' Problem" }, summary: { ko: "비신뢰 채널 위에서 두 당사자가 확정적 합의에 도달하는 것이 왜 불가능한지 이해하고, 현대 분산 시스템이 이 불가능성과 어떻게 타협하는지 구분할 수 있습니다. At-least-once와 멱등성이 표준이 된 근본 이유를 설명합니다.", en: "Why two parties cannot reach certain agreement over an unreliable channel, and how modern distributed systems live with that impossibility. Explains the foundational reason at-least-once delivery and idempotency became the norm." } }],
  ["effective-java-classes-and-interfaces", { slug: "effective-java-classes-and-interfaces", title: { ko: "클래스와 인터페이스", en: "Classes and Interfaces" }, summary: { ko: "이펙티브 자바 3판 4장 클래스와 인터페이스에서 핵심 7가지 아이템을 한 글로 정리합니다. 접근 권한 최소화부터 멤버 클래스의 static 결정까지 자바 예시 코드와 Before/After 비교로 따라갑니다.", en: "Seven core items from Effective Java 3E Chapter 4 — minimizing access, immutability, composition, designing for inheritance, interfaces over abstract classes, hierarchies over tagged classes, and static member classes — illustrated with Java samples." } }],
  ["redis-essentials", { slug: "redis-essentials", title: { ko: "Redis 입문", en: "Redis Essentials" }, summary: { ko: "Redis가 왜 다중 인스턴스 환경에서 표준 공용 메모리 계층이 되었는지 이해하고, 싱글 스레드 이벤트 루프·7종 자료구조·영속성 설정의 내부 동작을 파악합니다. 분산 락·Rate Limiting·세션·리더보드·메시징 5가지 대표 영역을 훑으며 어떤 Redis 기능이 어떤 문제에 맞닿아 있는지 정리합니다.", en: "Understand why Redis became the standard shared-memory layer in multi-instance systems, and how its single-thread event loop, seven data structures, and persistence options work internally. Surveys five areas (distributed locks, rate limiting, sessions, leaderboards, messaging) where Redis fits." } }],
  ["python-microbatcher", { slug: "python-microbatcher", title: { ko: "Python MicroBatcher", en: "Python MicroBatcher" }, summary: { ko: "짧은 시간 창 안에 들어온 여러 개별 호출을 한 번에 묶어 처리하는 Python MicroBatcher 패턴을 이해하고, asyncio 기반 최소 구현과 size/time 이중 flush 문법을 익히며, 지연 시간 vs 처리량 트레이드오프의 판단 기준을 얻습니다.", en: "Understand the Python MicroBatcher pattern, which groups individual async calls arriving within a short window into a single batch. Learn the minimal asyncio implementation, the size/time dual-flush syntax, and the latency vs throughput tradeoff." } }],
  ["idempotency", { slug: "idempotency", title: { ko: "멱등성", en: "Idempotency" }, summary: { ko: "같은 요청을 여러 번 보내도 한 번 보낸 것과 동일한 결과를 보장하는 멱등성이 왜 필요하고 어떻게 구현되는지 이해합니다. HTTP 메서드 의미론부터 Idempotency-Key 패턴, 자연 멱등 설계까지의 내부 동작을 정리합니다.", en: "Why idempotency matters and how it is implemented: delivering the same request N times should leave the system in the same final state as a single delivery. Covers HTTP method semantics, the Idempotency-Key pattern, and naturally idempotent design." } }],
  ["dense-and-sparse-vectors", { slug: "dense-and-sparse-vectors", title: { ko: "희소 벡터와 밀집 벡터", en: "Sparse and Dense Vectors" }, summary: { ko: "텍스트를 벡터로 부호화하는 두 가지 표현(dense, sparse)이 어떤 정보를 담고 무엇을 잃는지, 0 분포라는 한 가지 사실이 어떻게 인덱스 구조(HNSW vs Inverted Index)를 강제했는지, 두 표현이 결국 hybrid로 수렴하는 이유까지 정리합니다.", en: "Understand the two ways to encode text as vectors (dense and sparse), what each captures and loses, how a single fact about zero distribution forces the choice of index structure (HNSW vs Inverted Index), and why hybrid is the natural endpoint." } }],
  ["backpressure", { slug: "backpressure", title: { ko: "Backpressure", en: "Backpressure" }, summary: { ko: "소비자가 생산자보다 느릴 때 시스템이 OOM이나 지연 누적으로 무너지지 않도록 역방향 제어 신호를 보내는 backpressure의 개념을 이해하고, Buffer · Drop · Block · Signal 네 전략이 왜 논리적으로 완결적인지, 맥락별로 어떤 전략을 선택할지의 기준을 얻습니다.", en: "Understand backpressure as the reverse control signal that keeps a pipeline from collapsing into OOM or lag when the consumer lags the producer. Learn why Buffer, Drop, Block, and Signal are the only four strategies, and how to pick among them by context." } }],
  ["rag", { slug: "rag", title: { ko: "RAG", en: "RAG (Retrieval-Augmented Generation)" }, summary: { ko: "LLM이 가중치 안에 없는 지식을 답하는 방법을 이해할 수 있습니다. 의미 검색이 벡터 공간의 최근접 이웃 탐색으로 환원되는 원리, chunking과 ANN의 트레이드오프, Fine-tuning과 Long-context와의 선택 기준까지 다룹니다.", en: "How LLMs answer with knowledge that isn't in their weights. Understand semantic search reduced to nearest-neighbor search in vector space, chunking and ANN tradeoffs, and when to pick RAG over fine-tuning or long-context." } }],
  ["vector-database-primer", { slug: "vector-database-primer", title: { ko: "Vector Database 입문", en: "Vector Database Primer" }, summary: { ko: "Vector Database가 왜 기존 B+Tree 인덱스로는 풀 수 없는 고차원 유사도 검색 문제에 특화되었는지 이해합니다. cosine·L2·dot 거리 메트릭과 HNSW·IVF·PQ ANN 인덱스가 recall과 latency를 어떻게 trade-off하는지 메커니즘 감각으로 파악합니다.", en: "Understand why Vector Databases specialize for high-dimensional similarity search that B+Tree indexes cannot solve. See how distance metrics (cosine, L2, dot) and ANN indexes (HNSW, IVF, PQ) trade recall for latency at the mechanism level." } }],
  ["database-index-deep-dive", { slug: "database-index-deep-dive", title: { ko: "데이터베이스 인덱스", en: "Database Index" }, summary: { ko: "B+Tree 기반 인덱스의 내부 동작 원리를 이해하고, 복합 인덱스의 리프 노드 배치부터 등호 먼저·정렬 마지막 원칙, 인덱스 개수 결정까지 실전 설계 기준을 얻습니다.", en: "How B+Tree-based indexes work under the hood, from composite-index leaf layout to the equality-first/sort-last rule and deciding how many indexes to add." } }],
  ["k6-essentials", { slug: "k6-essentials", title: { ko: "k6 입문", en: "k6 Essentials" }, summary: { ko: "k6가 왜 개발자 친화적 부하 테스트 도구로 자리 잡았는지 이해하고, VU 개념과 스크립트 구조(default function, options, setup/teardown, stages, check, group/tag)부터 실행과 결과 해석까지 처음 사용 시 필요한 기초를 정리합니다.", en: "Understand why k6 became a developer-friendly load testing tool, and learn the basics of running your first test: the VU model, script structure (default function, options, setup/teardown, stages, check, group/tag), execution, and reading the summary report." } }],
  ["mini-coupang-order-concurrency-locks", { slug: "mini-coupang-order-concurrency-locks", title: { ko: "분산 환경에서 재고 서비스의 원자성 보장", en: "Inventory Service Atomicity in Distributed Environments" }, summary: { ko: "단일 SKU에 200 스레드가 동시 주문할 때 lost update가 어떻게 일어나는지, synchronized·비관적 락·Luascript + Saga Pattern이 정합성 전략을 어떻게 바꾸는지를 측정 결과와 코드로 비교합니다. 잠금 위치를 도메인 메서드에서 JVM 모니터, DB 행 락으로 이동시킨 뒤, 결제 같은 외부 호출이 끼어드는 순간 잠금 모델 자체를 원자 선점 + 보상 트랜잭션으로 바꾸는 과정을 추적합니다.", en: "How 200 concurrent orders on a single SKU produce lost update, then how synchronized, pessimistic lock, and Lua-based reservation with Saga compensation evolve the consistency strategy. Tracks how the model shifts from lock placement (JVM monitor → DB row) to atomic reserve + compensation when slow external payment calls enter the picture, with measurements." } }],
  ["effective-java-object-creation-and-destruction", { slug: "effective-java-object-creation-and-destruction", title: { ko: "객체의 생성과 파괴", en: "Object Creation and Destruction" }, summary: { ko: "이펙티브 자바 3판 2장 객체의 생성과 파괴에서 다섯 가지 아이템을 골라 정리합니다. 정적 팩토리, 빌더, private 생성자, 참조 해제, try-with-resources를 자바 예시 코드와 Before/After 비교로 살펴봅니다.", en: "A walk through five items from Effective Java 3E Chapter 2 — static factory methods, the Builder pattern, private constructors, reference nulling, and try-with-resources — with Java samples and before/after comparisons." } }],
  ["threadlocal-internals", { slug: "threadlocal-internals", title: { ko: "ThreadLocal", en: "ThreadLocal" }, summary: { ko: "ThreadLocal이 왜 '각 스레드가 자기 Map을 들고 있는 구조'로 수렴했는지 이해하고, 키 WeakReference와 값 strong reference의 비대칭이 어떻게 스레드 풀 메모리 누수를 만드는지 구분합니다. Virtual Thread와 ScopedValue가 ThreadLocal을 어떻게 대체하는지의 기준도 함께 얻습니다.", en: "Why ThreadLocal converged on the 'each Thread holds its own Map' structure, and how the key-as-WeakReference / value-as-strong asymmetry leads to memory leaks in thread pools. Includes when to pick ScopedValue over ThreadLocal with Virtual Threads." } }],
  ["kernel-primer", { slug: "kernel-primer", title: { ko: "커널", en: "Kernel" }, summary: { ko: "커널이 왜 필요하고 내부에서 어떻게 동작하는지 이해합니다. CPU 특권 레벨과 유저/커널 모드 분리, 시스템 콜이라는 유일한 통로, 그리고 모놀리식과 마이크로커널이 각각 어떤 상황에 수렴했는지를 메커니즘 감각으로 따라갑니다.", en: "Understand why kernels exist and how they work internally. Walk through CPU privilege rings, user/kernel mode separation, syscalls as the only legal crossing point, and why monolithic and microkernel architectures converged to different niches." } }],
  ["lexical-vs-semantic-search", { slug: "lexical-vs-semantic-search", title: { ko: "Lexical vs Semantic 검색", en: "Lexical vs Semantic Search" }, summary: { ko: "Lexical과 Semantic이 서로 다른 '관련성'을 측정한다는 것, 각자의 내부 파이프라인(inverted index + BM25, embedding + ANN)이 어떤 한계를 가지는지, 그리고 RRF로 두 축을 결합하는 것이 왜 단순 점수 합보다 견고한지 이해할 수 있습니다.", en: "Understand how lexical and semantic search measure 'relevance' differently, what limits each pipeline (inverted index + BM25 vs embedding + ANN), and why RRF is more robust than naive score addition when combining the two axes." } }],
  ["cardinality", { slug: "cardinality", title: { ko: "카디널리티", en: "Cardinality" }, summary: { ko: "카디널리티가 무엇인지 이해하고, 높은/낮은 카디널리티가 인덱스·캐시·파티셔닝 등 다양한 영역에서 어떤 영향을 주는지 판단하는 기준을 얻습니다.", en: "What cardinality means, and how high vs low cardinality shapes decisions across indexing, caching, and partitioning." } }],
  ["kafka-essentials", { slug: "kafka-essentials", title: { ko: "Kafka 입문", en: "Kafka Essentials" }, summary: { ko: "Kafka가 왜 탄생했고, 언제 쓰며, 사용 전 반드시 알아야 하는 핵심 개념(Broker, Topic, Partition, Offset, Producer, Consumer, Consumer Group)을 이해할 수 있습니다. SOA의 한계에서 출발해 분산 append-only log로 수렴한 설계 선택의 이유를 추적합니다.", en: "Understand why Kafka was born, when to use it, and the core concepts every engineer must know before using it: Broker, Topic, Partition, Offset, Producer, Consumer, Consumer Group. Traces the design choices that converged on a distributed append-only log as SOA hit its scaling limits." } }],
  ["cache-stampede", { slug: "cache-stampede", title: { ko: "캐시 스탬피드", en: "Cache Stampede" }, summary: { ko: "캐시 만료가 동시성과 만나 DB 부하가 폭주하는 Cache Stampede 문제의 근본 원인을 이해하고, Mutex Lock, Single Flight, Probabilistic Early Expiration, Stale-While-Revalidate 4가지 방어 패턴의 트레이드오프를 비교해 상황에 맞는 해법을 선택하는 기준을 얻습니다.", en: "Why cache expiration combined with concurrency overwhelms the database, and how to compare the four mitigation patterns (Mutex Lock, Single Flight, Probabilistic Early Expiration, Stale-While-Revalidate) to choose the right defense for your context." } }],
  ["cache-aside-pattern", { slug: "cache-aside-pattern", title: { ko: "Cache-Aside 패턴", en: "Cache-Aside Pattern" }, summary: { ko: "Cache-Aside가 왜 다른 캐싱 전략보다 먼저 채택되는지 그 구조적 이유와, 앱·캐시·DB 3자 상호작용의 내부 메커니즘, 쓰기 순서에서 발생하는 race condition을 이해합니다. Read-Through, Write-Through, Write-Behind, Write-Around와의 트레이드오프를 비교해 상황에 맞는 캐싱 패턴을 선택하는 기준을 얻습니다.", en: "Why Cache-Aside is the default choice among caching patterns, how the three-actor interaction (app, cache, DB) actually works, and where write races and stale reads come from. Compare Read-Through, Write-Through, Write-Behind, and Write-Around to choose the right pattern for your context." } }],
  ["coroutine-primer", { slug: "coroutine-primer", title: { ko: "코루틴", en: "Coroutine" }, summary: { ko: "코루틴이 OS 스레드로는 풀 수 없는 C10K 문제를 어떻게 해결했는지 이해하고, suspend/resume의 내부 메커니즘(state machine 변환, Continuation 객체, Event Loop 협력)과 Stackless/Stackful의 구현 분기를 구분합니다. Python asyncio와 Kotlin Coroutines 문법을 나란히 보여주며, CPU-bound 작업에서 코루틴을 피해야 하는 이유까지 다룹니다.", en: "Why coroutines solve what OS threads cannot in C10K, how suspend/resume works (state machine, Continuation, Event Loop), and how Stackless vs Stackful implementations diverge. Covers Python asyncio and Kotlin Coroutines side by side, with guidance on when to avoid coroutines for CPU-bound work." } }],
  ["innodb-explain-reading", { slug: "innodb-explain-reading", title: { ko: "InnoDB EXPLAIN 소개", en: "InnoDB EXPLAIN Introduction" }, summary: { ko: "InnoDB EXPLAIN의 12개 컬럼이 무엇을 의미하는지 이해하고, type/key/Extra를 중심으로 슬로우 쿼리의 원인을 진단하는 기준을 얻습니다.", en: "Understand what each of InnoDB EXPLAIN's 12 columns means, and learn to diagnose slow queries by reading the type, key, and Extra columns." } }],
  ["quick-sort", { slug: "quick-sort", title: { ko: "퀵 정렬", en: "Quick Sort" }, summary: { ko: "분할 정복 기반의 대표적인 비교 정렬 알고리즘인 Quick Sort의 동작 원리, 구현, 시간 복잡도, 주의사항을 한 페이지에 정리합니다. 이 글은 Backend Notes의 모든 MDX 문법 스타일 가이드를 겸합니다.", en: "Quick Sort, the classic divide-and-conquer comparison sort, covered end to end: mechanics, implementation, time complexity, and pitfalls. Doubles as the MDX syntax style guide for this blog." } }],
  ["trie-prefix-tree", { slug: "trie-prefix-tree", title: { ko: "트라이", en: "Trie" }, summary: { ko: "트라이가 왜 HashMap으로 풀 수 없는 접두어 검색 문제를 구조 자체로 해결하는지 이해하고, 노드 구조와 삽입/탐색 내부 동작, 메모리 폭발을 완화하는 Compressed Trie·Radix Tree·Aho-Corasick 같은 진화를 구분할 수 있습니다.", en: "How Trie solves prefix-search problems that HashMap structurally cannot, via per-character branching and path sharing. Covers node layout, insert/search mechanics, and the memory tradeoff that drives variants like Compressed Trie, Radix Tree, and Aho-Corasick." } }],
  ["pagination-offset-vs-cursor", { slug: "pagination-offset-vs-cursor", title: { ko: "페이지네이션: OFFSET vs Cursor", en: "Pagination: OFFSET vs Cursor" }, summary: { ko: "OFFSET/LIMIT과 Cursor 기반 페이지네이션의 근본 차이를 이해하고, 왜 OFFSET이 deep page에서 선형으로 느려지는지 B+Tree 인덱스 레벨로 파악합니다. 두 방식의 성능·일관성·UX 트레이드오프를 비교해 상황에 맞는 선택 기준을 얻습니다.", en: "Understand the fundamental difference between OFFSET/LIMIT and cursor-based pagination, and why OFFSET degrades linearly at deep pages at the B+Tree index level. Compare their performance, consistency, and UX tradeoffs to choose the right approach for your context." } }],
  ["full-table-scan", { slug: "full-table-scan", title: { ko: "Full Table Scan", en: "Full Table Scan" }, summary: { ko: "Full Table Scan이 언제 문제이고 언제 정상인지 구분할 수 있습니다. 옵티마이저가 인덱스 대신 Full Table Scan을 선택하는 이유와 Sequential I/O vs Random I/O 트레이드오프를 이해합니다.", en: "When a full table scan is a problem and when it is not. Why the optimizer sometimes prefers a scan over an index, and how Sequential I/O vs Random I/O drives that choice." } }],
  ["ddd-overview", { slug: "ddd-overview", title: { ko: "도메인 주도 설계 (DDD)", en: "Domain-Driven Design" }, summary: { ko: "DDD가 왜 복잡한 비즈니스 로직을 Service 분기로 푸는 방식의 대안으로 등장했는지 이해하고, Bounded Context · Aggregate · Ubiquitous Language 같은 핵심 용어가 각각 어떤 문제를 해결하는 도구인지 구분할 수 있습니다.", en: "Why DDD emerged as an alternative to tangled Service-layer branches in complex business logic, and how to distinguish what problem each core term (Bounded Context, Aggregate, Ubiquitous Language) solves." } }],
  ["kyc-primer", { slug: "kyc-primer", title: { ko: "KYC (Know Your Customer)", en: "KYC (Know Your Customer)" }, summary: { ko: "KYC가 무엇이고 왜 필요한지, 어떤 검증 단계로 구성되는지 이해할 수 있습니다. 헷갈리기 쉬운 AML, CDD, EDD, KYB의 포함 관계와 축 차이를 정리하고, 전통 금융에서 가상자산 거래소까지 KYC 의무가 확장된 궤적을 살펴봅니다.", en: "Understand what KYC is, why it matters, and what verification steps make it up. Learn to distinguish the often-conflated AML, CDD, EDD, and KYB by their containment and scope, and trace how KYC obligations expanded from traditional banking to virtual asset exchanges." } }],
  ["b-tree-structure", { slug: "b-tree-structure", title: { ko: "B-Tree", en: "B-Tree" }, summary: { ko: "B-Tree가 왜 디스크 기반 시스템의 표준 자료구조가 되었는지 이해하고, 탐색·삽입·분할의 내부 동작 원리와 B+Tree·해시 인덱스와의 트레이드오프를 구분할 수 있습니다.", en: "Why B-Tree became the standard data structure for disk-based systems. Covers search, insert, and split mechanics, plus how it trades off against B+Tree and hash indexes." } }],
  ["bm25", { slug: "bm25", title: { ko: "BM25", en: "BM25" }, summary: { ko: "BM25가 왜 TF-IDF를 넘어섰는지, TF 포화와 문서 길이 정규화라는 두 축이 어떻게 작동하는지 이해할 수 있습니다. 파라미터 k1과 b가 각 축의 강도를 어떻게 돌리는지, 하이브리드 검색에서 어디에 자리 잡는지까지 수식 감각으로 정리합니다.", en: "Understand why BM25 supersedes TF-IDF and how its two axes (TF saturation and document length normalization) work. Covers what the k1 and b parameters dial, and where BM25 sits in a modern hybrid search stack." } }],
  ["change-data-capture", { slug: "change-data-capture", title: { ko: "Change Data Capture (CDC)", en: "Change Data Capture (CDC)" }, summary: { ko: "dual-write 문제가 왜 원자적으로 해결되지 않는지, 그리고 CDC가 DB의 트랜잭션 로그를 재활용해 이 문제를 어떻게 우회하는지 이해할 수 있습니다. 쿼리 기반, 트리거 기반, 로그 기반 세 가지 구현 방식의 내부 동작과 로그 기반이 실전 표준이 된 CS 인과 관계를 구분할 수 있습니다.", en: "Understand why the dual-write problem has no atomic solution, and how CDC sidesteps it by reusing the database's transaction log. Compare the internals of query-based, trigger-based, and log-based implementations, and see the CS-level causality that made log-based CDC the practical standard." } }],
  ["redis-lua-scripting", { slug: "redis-lua-scripting", title: { ko: "Redis Lua Scripting", en: "Redis Lua Scripting" }, summary: { ko: "Redis에서 Luascript가 왜 필요한지(다중 명령 원자성과 RTT 절감), 단일 스레드 이벤트 루프 위에서 어떻게 실행되는지(스크립트 캐시, KEYS/ARGV, redis.call), 운영에서 마주치는 블로킹/비결정성/Cluster 제약을 정리합니다.", en: "Explains why Redis Lua scripting exists (multi-command atomicity and RTT reduction), how it executes on the single-threaded event loop (script cache, KEYS/ARGV, redis.call), and operational pitfalls around blocking, non-determinism, and Cluster constraints." } }],
  ["mono-flux-primer", { slug: "mono-flux-primer", title: { ko: "Mono/Flux", en: "Mono/Flux" }, summary: { ko: "Spring Reactive와 WebFlux를 처음 접하는 입문자를 위한 Mono/Flux 정리. Publisher 개념과 Cold/Lazy 실행 모델, 연산자 체인이 왜 CompletableFuture 체인보다 편한지, 그리고 입문자가 가장 자주 만드는 4가지 실수(구독 누락, 블로킹 호출 혼입, map/flatMap 혼동, 에러 처리 누락)까지 다룹니다.", en: "A beginner primer on Mono/Flux for newcomers to Spring Reactive/WebFlux. Covers the Publisher model, Cold/Lazy execution, why operator chains beat CompletableFuture, and the four most common beginner mistakes (missing subscribe, blocking calls, map vs flatMap, error handling)." } }],
  ["jvm-gc-intro", { slug: "jvm-gc-intro", title: { ko: "JVM 가비지 컬렉션", en: "JVM Garbage Collection" }, summary: { ko: "JVM GC가 왜 필요하고, 힙 구조와 세대별 수거가 어떻게 동작하며, 알고리즘별 트레이드오프를 판단하는 기준을 얻습니다.", en: "Why JVM GC exists, how the heap is structured, how generational collection works, and the tradeoffs between the major algorithms." } }],
  ["grpc-essentials", { slug: "grpc-essentials", title: { ko: "gRPC 입문", en: "gRPC Essentials" }, summary: { ko: "gRPC가 왜 만들어졌고, REST 대비 어떤 문제를 해결하며, .proto 정의부터 서버와 클라이언트 구현까지 입문에 필요한 흐름을 이해할 수 있습니다. HTTP/2와 Protobuf가 결합해 만들어내는 RPC의 새 형태를 살펴봅니다.", en: "Understand why gRPC was created, what problems it solves over REST, and the basic flow from .proto definition through server and client implementation. Explores the new shape of RPC that HTTP/2 and Protobuf together create." } }],
  ["kafka-replication", { slug: "kafka-replication", title: { ko: "Kafka Replication", en: "Kafka Replication" }, summary: { ko: "Kafka가 브로커 장애에도 데이터 유실 없이 동작하는 복제 메커니즘을 이해할 수 있습니다. Leader/Follower 역할, ISR(In-Sync Replica)의 편입과 축출 기준, acks 옵션과 min.insync.replicas의 실제 보장, 리더 장애 시 Controller가 주관하는 재선출 과정까지, HA가 만들어지는 과정을 따라갑니다.", en: "Understand how Kafka stays resilient through broker failures. Covers Leader/Follower roles, how replicas enter and leave the ISR set, what acks and min.insync.replicas actually guarantee, and how the Controller re-elects a leader when a broker dies." } }],
  ["instant-vs-localdatetime", { slug: "instant-vs-localdatetime", title: { ko: "Instant vs LocalDateTime", en: "Instant vs LocalDateTime" }, summary: { ko: "Instant · LocalDateTime · ZonedDateTime · OffsetDateTime 네 가지 Java Time 타입이 각각 무엇을 모델링하는지 이해하고, Hibernate와 MySQL을 거치는 세 층의 타임존 해석을 따라가며, 감사 필드 · 예약 시각 · 국제 일정에서 어느 타입을 고를지 기준을 얻을 수 있습니다.", en: "Understand what each of Java Time's four types (Instant, LocalDateTime, ZonedDateTime, OffsetDateTime) models, follow the three layers of timezone interpretation through Hibernate and MySQL, and learn how to choose the right type for audit fields, reservations, and cross-timezone schedules." } }],
  ["k-nearest-neighbors", { slug: "k-nearest-neighbors", title: { ko: "kNN (k-Nearest Neighbors)", en: "kNN (k-Nearest Neighbors)" }, summary: { ko: "kNN은 새 점이 들어오면 가장 가까운 k개 이웃의 답을 모아 결정하는 가장 단순한 학습 알고리즘입니다. 학습 단계가 거의 없는 이유, 결정 경계가 데이터 분포 모양 그대로 형성되는 이유, 그리고 점이나 차원이 커지면 근사 검색으로 넘어가는 지점을 직관적으로 이해합니다.", en: "kNN classifies a new point by polling the labels of its k closest neighbors. Understand why this simple algorithm needs almost no training, why its decision boundary follows the data, and where exact search gives way to approximate methods at scale." } }],
  ["lettuce-vs-redisson", { slug: "lettuce-vs-redisson", title: { ko: "Lettuce vs Redisson", en: "Lettuce vs Redisson" }, summary: { ko: "Spring 백엔드에서 가장 흔히 만나는 두 Redis 클라이언트의 차이를 내부 동작 수준에서 정리합니다. Lettuce는 명령을 그대로 보내는 얇은 클라이언트, Redisson은 분산 락과 자료구조를 Java/Kotlin 객체처럼 다루게 해주는 두꺼운 라이브러리입니다.", en: "A side-by-side look at the two Redis clients most Spring backends actually choose. Lettuce is a thin Netty-based command sender; Redisson is a thicker library that exposes distributed locks and structures as Java/Kotlin objects." } }],
  ["redis-template-essentials", { slug: "redis-template-essentials", title: { ko: "RedisTemplate 입문", en: "RedisTemplate Essentials" }, summary: { ko: "Spring Data Redis의 RedisTemplate으로 Redis 명령을 호출하는 사용법 입문. 의존성 추가, ConnectionFactory 자동 구성, Serializer 4-슬롯, 7종 opsForXxx 진입점, 그리고 캐시·카운터·해시 프로필 세 시나리오까지 처음 사용 시 필요한 기초를 정리합니다.", en: "A getting-started guide to Spring Data Redis's RedisTemplate. Walks through Gradle dependencies, the auto-configured ConnectionFactory, the four serializer slots, the seven opsForXxx entry points, and three small scenarios (cached read, counter, profile hash)." } }],
  ["qdrant-scalar-quantization", { slug: "qdrant-scalar-quantization", title: { ko: "Qdrant Scalar Quantization", en: "Qdrant Scalar Quantization" }, summary: { ko: "Qdrant의 Scalar Quantization이 fp32 벡터를 int8로 바꿔 메모리 4배 절약과 SIMD 가속을 얻는 대신 recall을 얼마나 양보하는지, quantile·rescore·oversampling·always_ram 옵션이 어느 축을 움직이는지 내부 동작 중심으로 정리합니다.", en: "Understand how Qdrant Scalar Quantization trades recall for 4x memory savings and SIMD-accelerated distance by mapping fp32 to int8, and which axis each option (quantile, rescore, oversampling, always_ram) moves inside the pipeline." } }],
  ["qdrant-primer", { slug: "qdrant-primer", title: { ko: "Qdrant 입문", en: "Qdrant Getting Started" }, summary: { ko: "Qdrant를 로컬에 띄우고 Python client로 collection 생성, upsert, search, payload 필터까지 이어지는 입문 흐름을 따라갑니다. 차원과 거리 메트릭 고정, payload 인덱스, 비동기 인덱싱 같은 입문 단계의 함정을 함께 정리합니다.", en: "Walk through the Qdrant beginner flow: spin up the server, connect with the Python client, and follow create collection, upsert, search, and payload filter in sequence. Along the way, cover common beginner pitfalls: fixed dimension and distance, payload indexes, and asynchronous indexing." } }],
])
